-- 멱등: on conflict do update

on conflict (tenant_id,category,subcategory,item_name) do update set required_data_fields = excluded.required_data_fields, source_candidates = excluded.source_candidates, priority = excluded.priority, data_status = excluded.data_status, owner = excluded.owner, update_cycle = excluded.update_cycle, connections = excluded.connections, origin_dataset = excluded.origin_dataset, notes = excluded.notes, updated_at = now();

